package com.gasczoology.invertebratelab.data

import com.google.gson.JsonParser

/** Visible attribution line for one plate slot, in both app languages. */
data class PlateCredit(val en: String, val ta: String) {
    fun text(language: AppLanguage): String = if (language == AppLanguage.TAMIL) ta else en
}

/**
 * Parses assets/type_studies/plate_credits.json:
 *   { "pila/torsion": { "en": "...", "ta": "..." }, ... }
 * The file is generated by tools/plate_intake.py from provenance/plates.json, so
 * every image added through the tool is credited automatically.
 * Malformed or missing data yields an empty map (no credit shown), never a crash.
 */
object PlateCreditParser {
    fun parse(json: String): Map<String, PlateCredit> {
        if (json.isBlank()) return emptyMap()
        return runCatching {
            val out = linkedMapOf<String, PlateCredit>()
            for ((slot, value) in JsonParser.parseString(json).asJsonObject.entrySet()) {
                val o = value.asJsonObject
                val en = o.get("en")?.asString.orEmpty().trim()
                val ta = o.get("ta")?.asString.orEmpty().trim()
                if (en.isNotEmpty()) out[slot] = PlateCredit(en, ta.ifEmpty { en })
            }
            out
        }.getOrDefault(emptyMap())
    }
}
